import { expect, test } from "bun:test";

import { reclaimCause, recoveryBudget, summarizeReclaims } from "../src/recovery.ts";

test("reclaimCause reads string causes only", () => {
  expect(reclaimCause({ cause: "orphan_requeue" })).toBe("orphan_requeue");
  expect(reclaimCause({ cause: "" })).toBeNull();
  expect(reclaimCause({ cause: 7 })).toBeNull();
  expect(reclaimCause(null)).toBeNull();
});

test("recoveryBudget clamps remaining at zero", () => {
  expect(recoveryBudget({ attempt: 1, max_attempts: 3 })).toEqual({
    attempt: 1,
    max_attempts: 3,
    remaining: 2,
    exhausted: false,
  });
  expect(recoveryBudget({ attempt: 5, max_attempts: 3 })).toEqual({
    attempt: 5,
    max_attempts: 3,
    remaining: 0,
    exhausted: true,
  });
});

test("summarizeReclaims counts reoffer causes in order", () => {
  expect(
    summarizeReclaims([
      { kind: "claim", meta: { cause: "decoy" } },
      { kind: "claim.reoffer", meta: { cause: "orphan_requeue" } },
      { kind: "claim.reoffer", meta: { cause: "provider_cap" } },
      { kind: "claim.reoffer", meta: {} },
    ]),
  ).toEqual({ requeues: 2, causes: ["orphan_requeue", "provider_cap"] });
});
